   {
    "term": "specialised cell",
    "def": "A cell with a structure suited to one particular function, such as a red blood cell, which transports oxygen."
   },
   {
    "term": "ciliated cell",
    "def": "A cell lining the trachea and bronchi, with many tiny hairs (cilia) on its surface. The cilia move mucus."
   },
   {
    "term": "root hair cell",
    "def": "A cell on the surface of a root with a long, thin extension into the soil. The root hairs together give a large surface area, which increases the uptake of water (by osmosis) and mineral ions (by active transport)."
   },
   {
    "term": "palisade mesophyll",
    "def": "The layer of tightly packed, column-shaped cells under the upper epidermis of a leaf, holding most of its chloroplasts. Where most photosynthesis happens."
   },
   {
    "term": "neurone",
    "def": "A nerve cell. Neurones conduct electrical impulses."
   },
   {
    "term": "red blood cell",
    "def": "A blood cell that transports oxygen. It is full of haemoglobin and has no nucleus."
   },
   {
    "term": "gamete",
    "def": "A sex cell: a sperm cell or an egg cell. Two gametes fuse at fertilisation."
   }
